// === Tab: mySketch ===
/* ============================================================
   Diamond — 海底节奏完整版（Version C）
   - 完整海底生态（鱼/乌龟/水母/远景）
   - 水下光斑（caustics）、雾、漂浮微尘
   - 音符：0-9 各种形状 + 固定颜色 + 随机大小
   - 防止同 lane 紧挨生成、判定线、尾部爆裂粒子
   - 数字为白字 + 黑描边确保可读
   ===========================================================*/
/* -------------------------
   全局变量（先声明，避免 TDZ）
--------------------------*/
let notes = [];
let particles = [];
let floatingDust = [];
let nextNoteTime = 0;
const lanes = 9;
const laneHeight = 70;
const speed = 3;
let judgementX = 1000;
const judgementTargetX = 300;
let lastNoteX = []; // 记录每条 lane 最后一个音符起始 X
// 数字颜色 hex（用 hex 存，setup 中转换为 p5 color）
const digitColorsHex = {
  0: "#33a8c7",
  1: "#52e3e1",
  2: "#a0e426",
  3: "#fdf148",
  4: "#ffab00",
  5: "#f77976",
  6: "#f050ae",
  7: "#d883ff",
  8: "#9336fd",
  9: "#ff66cc"
};
let digitColors = {}; // p5 color map
// 海底生态数组（提前声明）
let fishes = [];
let turtles = [];
let jellies = [];
let corals = [];
let seaweeds = [];
let bubbles = [];
let farFish = [];
// 图层
let causticsG, fogG;
// 性能/视觉参数（方便调）
const CAUSTICS_DROPLETS = 110;
const MAX_FLOATING_DUST = 160;
const NOTE_MIN_SIZE = 80;
const NOTE_MAX_SIZE = 100;
/* -------------------------
   setup
--------------------------*/
function setup() {
  createCanvas(1600, 900);
  pixelDensity(1);
  textAlign(CENTER, CENTER);
  textFont('Helvetica');
  rectMode(CENTER);
  angleMode(RADIANS);
  // 转换颜色
  for (let k in digitColorsHex) digitColors[k] = color(digitColorsHex[k]);
  // 初始化 lastNoteX
  lastNoteX = Array(lanes).fill(-9999);
  // 生态初始化
  for (let i = 0; i < 20; i++) addFish();
  for (let i = 0; i < 6; i++) addTurtle();
  for (let i = 0; i < 10; i++) addJelly();
  for (let i = 0; i < 14; i++) addCoral();
  for (let i = 0; i < 28; i++) addSeaweed();
  for (let i = 0; i < 12; i++) addFarFish();
  // 图层
  causticsG = createGraphics(width, height);
  fogG = createGraphics(width, height);
  buildCaustics();
  buildFog();
  nextNoteTime = millis() + random(500, 700);
}
/**
 * 返回一个在 minY ~ maxY 内、与已有音符保持 spacing 最小间距的 Y 坐标
 * @param {Array} existingNotes 当前正在屏幕上的音符列表
 * @param {number} minY 允许的最小 Y
 * @param {number} maxY 允许的最大 Y
 * @param {number} spacing 音符之间最小间隔
 * @param {number} maxTries 尝试次数，避免死循环
 */
const EFFECT_MARGIN = 10; // 粒子和柔光的最大半径
function getSafeY(minY, maxY, spacing = 180, maxTries = 300) {  // 减小spacing到180，允许更密集
  let y, tries = 0;
  let found = false;
  do {
    y = random(minY, maxY);
    tries++;
    // 自适应检查：考虑现有音符大小、新音符大小（近似max/2）和光晕margin
    const collision = notes.some(n => abs(n.y - y) < spacing + n.size/2 + (NOTE_MAX_SIZE/2) + EFFECT_MARGIN);
    if (!collision) {
      found = true;
      break;
    }
  } while (tries < maxTries);
  if (!found) {
    console.warn('No safe Y found after max tries');
    return null;  // 返回null，表示无法找到安全位置，不添加音符
  }
  return y;
}
/* -------------------------
   draw 主循环
--------------------------*/
function draw() {
  // 背景渐变（深海）
  drawBackground();
  // 光柱
  drawLightRays();
  // 海底植物
  drawSeaweeds();
  drawCorals();
  drawBubbles();
  // 生物（远景先，近景后）
  drawFarFish();
  drawFishes();
  drawTurtles();
  drawJellies();
  // 音符系统与判定线
  generateNotes();
  // drawLanes();
  drawJudgementLine();
  // caustics（加法叠加）和雾（叠乘）
  blendMode(ADD);
  image(causticsG, 0, 0);
  blendMode(BLEND);
  blendMode(MULTIPLY);
  image(fogG, 0, 0);
  blendMode(BLEND);
  // 漂浮微尘、粒子、音符
  updateFloatingDust();
  updateParticles();
  drawNotes();
}
/* ============================================================
   音符生成逻辑（带 lane 避免紧挨、颜色、大小、形状）
============================================================ */
/* -------------------------
   音符生成逻辑（去掉 lane，竖向分布，批量生成）
--------------------------*/
function generateNotes() {
  if (millis() >= nextNoteTime) {
    if (notes.length < 12) {  // 增大上限到12
      addNotesBatch();
    }
    nextNoteTime = millis() + floor(random(400, 1200));  // 减小间隔，增加频率
  }
}
function addNotesBatch() {
  let batchCount = int(random(5, 12)); // 增大到1~3个
  let minY = 120; // 竖向起点
  let maxY = height - 180; // 竖向终点
  let spacingY = 50;  // 与getSafeY一致，减小以允许更多
  for (let i = 0; i < batchCount; i++) {
    let num; // 声明变量
    let tries = 0;
    do {
      num = int(random(0, 10));
      tries++;
      let count = notes.filter(n => n.value === num).length;
      if (count < 10) break;
    } while (tries < 12);
    var y = getSafeY(minY, maxY, spacingY);
    if (y === null) continue;  // 如果无法找到安全Y，跳过添加
    let startX = width + random(50, 360);
    let sz = random(NOTE_MIN_SIZE, NOTE_MAX_SIZE);
    let shapes = ["circle","bar","triangle","square","diamond","pentagon","hexagon","star","heart","cloud"];
    let shape = shapes[num % shapes.length];
    notes.push({
      value: num,
      x: startX,
      y: y,
      duration: random(500, 1500),
      hit: false,
      tailDuration: 0,
      hitStartTime: 0,
      size: sz,
      color: digitColors[num], // 确保 digitColors[num] 正确
      shape: shape,
      jitterSeed: random(1000),
      speed: random(1.8, 4.2) // 每个音符独立速度
    });
  }
}
function drawNotes() {
  for (let n of notes) {
    // 基本移动 + 柔和垂直漂浮（水流感）
    n.x -= n.speed;
    n.y += sin((millis() * 0.001) + n.jitterSeed + n.x * 0.002) * 0.3;
    // 轻微折射抖动
    let refX = map(noise(n.x * 0.003, n.y * 0.003, millis()*0.0005), 0, 1, -6, 6);
    let refY = map(noise(n.x * 0.002, n.y * 0.004, millis()*0.0007+50), 0, 1, -4, 4);
    let drawX = n.x + refX;
    let drawY = n.y + refY;
    let distToJudge = abs(n.x - judgementX);
    let alpha = map(n.x, width, judgementX, 0, 255);
    alpha = constrain(alpha, 60, 255);
    let pulse = 1 + 0.12 * sin(millis() * 0.006 + n.value);
    // 判定线接触检测（触发 hit）
    if (!n.hit && distToJudge < 8) {
      n.hit = true;
      n.hitStartTime = millis();
      n.tailDuration = random(300, 1400);
    }
    // 若命中则持续尾部效果
    if (n.hit) {
      let elapsed = millis() - n.hitStartTime;
      if (elapsed < n.tailDuration) {
        // 小爆裂（但不要每帧都 spawn 太多）
        if (frameCount % 6 === 0) spawnExplosion(drawX, drawY);
        alpha = 255;
        pulse = 1.28;
      }
    }
    // 拖尾粒子（随机频率）
    if (frameCount % int(random(1, 4)) === 0) {
      let tailLife = n.hit ? n.tailDuration : random(300, 700);
      particles.push({
        x: drawX + random(-3, 3),
        y: drawY + random(-3, 3),
        alpha: random(80, 200),
        r: random(4, 10),
        decay: tailLife / 60,
        vx: random(-0.2, 0.2),
        vy: random(-0.6, 0.2)
      });
    }
    // 外圈柔光
    noStroke();
    fill(255, alpha * 0.08);
    ellipse(drawX, drawY, (n.size + 26) * pulse, (n.size + 26) * pulse);
    // 内圈底色（颜色稍微降低透明度以不遮挡数字）
    fill(red(n.color), green(n.color), blue(n.color), alpha * 0.8);
    ellipse(drawX, drawY, (n.size + 6) * pulse, (n.size + 6) * pulse);
    // 绘制形状（颜色填充）
    push();
    translate(drawX, drawY);
    rotate(0.02 * sin(millis() * 0.002 + n.jitterSeed));
    fill(red(n.color), green(n.color), blue(n.color), alpha * 0.95);
    noStroke();
    drawDigitShape(n.shape, n.size * pulse);
    pop();
    // 数字文字：白色 + 黑描边保证清晰
    push();
    fill(255);
    stroke(0);
    strokeWeight(6);
    textSize(max(12, n.size * 0.45) * pulse);
    textAlign(CENTER, CENTER);
    text(n.value, drawX, drawY);
    pop();
  }
  // 清理音符：离开屏幕（并且尾部效果已结束）
  notes = notes.filter(n => n.x > -80 || (n.hit && millis() - n.hitStartTime < n.tailDuration));
}
/* ============================================================
   形状绘制函数（为 0..9 提供各类形状）
============================================================*/
function drawDigitShape(shapeName, s) {
  // s 相当于直径尺度
  switch (shapeName) {
    case "circle":
      ellipse(0, 0, s, s);
      break;
    case "bar":
      rect(0, 0, s * 0.34, s * 1.08, s * 0.12);
      break;
    case "triangle":
      triangle(0, -s * 0.55, -s * 0.55, s * 0.45, s * 0.55, s * 0.45);
      break;
    case "square":
      rect(0, 0, s, s, s * 0.08);
      break;
    case "diamond":
      beginShape();
      vertex(0, -s * 0.6);
      vertex(s * 0.55, 0);
      vertex(0, s * 0.6);
      vertex(-s * 0.55, 0);
      endShape(CLOSE);
      break;
    case "pentagon":
      drawNGon(0, 0, s * 0.48, 5);
      break;
    case "hexagon":
      drawNGon(0, 0, s * 0.48, 6);
      break;
    case "star":
      drawStar(0, 0, s * 0.28, s * 0.55, 5);
      break;
    case "heart":
      drawHeart(0, 0, s * 0.9);
      break;
    case "cloud":
      drawCloud(0, 0, s * 0.9);
      break;
    default:
      ellipse(0, 0, s, s);
  }
}
function drawNGon(x, y, r, n) {
  push();
  translate(x, y);
  beginShape();
  for (let i = 0; i < n; i++) {
    let angle = TWO_PI / n * i - HALF_PI;
    vertex(cos(angle) * r, sin(angle) * r);
  }
  endShape(CLOSE);
  pop();
}
function drawStar(x, y, r1, r2, n) {
  push();
  translate(x, y);
  beginShape();
  for (let i = 0; i < n * 2; i++) {
    var angle = PI / n * i - HALF_PI;
    let r = (i % 2 === 0) ? r2 : r1;
    vertex(cos(angle) * r, sin(angle) * r);
  }
  endShape(CLOSE);
  pop();
}
function drawHeart(x, y, s) {
  push();
  translate(x, y);
  beginShape();
  vertex(0, s * 0.33);
  bezierVertex(-s * 0.5, s * -0.15, -s * 0.2, -s * 0.85, 0, -s * 0.45);
  bezierVertex(s * 0.2, -s * 0.85, s * 0.5, s * -0.15, 0, s * 0.33);
  endShape(CLOSE);
  pop();
}
function drawCloud(x, y, s) {
  push();
  translate(x, y);
  ellipse(-s * 0.28, 0, s * 0.6, s * 0.4);
  ellipse(s * 0.28, 0, s * 0.6, s * 0.4);
  ellipse(0, -s * 0.12, s * 0.8, s * 0.5);
  pop();
}
/* ============================================================
   判定线 / 车道（金箍棒）
============================================================*/
function drawLanes() {
  strokeWeight(2);
  for (let i = 0; i < lanes; i++) {
    var y = 100 + i * laneHeight;
    let glow = 90 + 70 * sin(millis() * 0.0016 + i * 0.3);
    stroke(150, 200, 240, glow);
    line(0, y, width, y);
  }
}
function drawJudgementLine() {
  // 平滑移动金箍棒向目标
  // judgementX += (judgementTargetX - judgementX) * 0.06;
  judgementX = 450; // 判定线移动到 x = 400
  let gcols = [color(255, 215, 0), color(255, 180, 0), color(255, 220, 120)];
  strokeWeight(12);
  noFill();
  for (let i = 0; i < gcols.length; i++) {
    stroke(gcols[i]);
    line(judgementX, 50 + i * 2, judgementX, height - 50 - i * 2);
  }
  fill(255, 215, 0);
  noStroke();
  ellipse(judgementX, 50, 20, 20);
  ellipse(judgementX, height - 50, 20, 20);
}
/* ============================================================
   粒子系统（尾部爆裂 + 拖尾） & 漂浮微尘
============================================================*/
function updateParticles() {
  for (let p of particles) {
    p.alpha -= p.decay;
    p.r *= 0.98;
    p.x += p.vx || 0;
    p.y += p.vy || -0.3; // 轻微上浮
    noStroke();
    fill(255, p.alpha);
    ellipse(p.x, p.y, p.r, p.r);
  }
  particles = particles.filter(p => p.alpha > 6 && p.r > 0.6);
}
function spawnExplosion(x, y) {
  // 一次爆裂生成多种粒子
  for (let i = 0; i < 10; i++) {
    let ang = random(TWO_PI);
    particles.push({
      x: x + cos(ang) * random(2, 18),
      y: y + sin(ang) * random(2, 18),
      alpha: random(140, 255),
      r: random(6, 18),
      decay: random(2.2, 4.2),
      vx: cos(ang) * random(0.2, 2.2),
      vy: sin(ang) * random(-0.8, 0.8)
    });
  }
  // 额外大一点的光圈
  for (let i = 0; i < 3; i++) {
    particles.push({
      x: x + random(-6, 6),
      y: y + random(-6, 6),
      alpha: 200,
      r: random(20, 36),
      decay: random(1.8, 3.0),
      vx: random(-0.2, 0.2),
      vy: random(-0.2, 0.2)
    });
  }
}
function updateFloatingDust() {
  // 控制总体数量
  if (floatingDust.length < MAX_FLOATING_DUST && random() < 0.05) {
    floatingDust.push({
      x: random(width),
      y: random(height),
      r: random(0.6, 3.2),
      alpha: random(20, 90),
      vx: random(-0.12, 0.45),
      vy: random(-0.06, 0.06)
    });
  }
  for (let d of floatingDust) {
    d.x += d.vx + sin(millis()*0.0006 + d.x*0.001)*0.06;
    d.y += d.vy + cos(millis()*0.0008 + d.y*0.001)*0.03;
    noStroke();
    fill(240, 245, 255, d.alpha);
    ellipse(d.x, d.y, d.r, d.r);
    d.alpha -= 0.02;
  }
  floatingDust = floatingDust.filter(d => d.alpha > 6);
}
/* ============================================================
   背景、光柱、caustics（光斑）、雾
============================================================*/
function drawBackground() {
  let t = millis() * 0.00022;
  for (let i = 0; i < height; i++) {
    let c1 = color(6, 24 + 10 * sin(t*1.1), 68);
    let c2 = color(2, 14 + 18 * sin(t + 3), 100);
    stroke(lerpColor(c1, c2, i / height));
    line(0, i, width, i);
  }
}
function drawLightRays() {
  noStroke();
  var t = millis() * 0.0008;
  for (let i = -1; i < 7; i++) {
    fill(255, 255, 255, 18 + 16 * sin(t + i));
    beginShape();
    vertex(i * 240 - 200 + sin(t + i*0.7) * 60, 0);
    vertex(i * 240 + 70 + sin(t + i*0.6) * 60, 0);
    vertex(i * 240 + 180, height);
    vertex(i * 240 - 180, height);
    endShape(CLOSE);
  }
}
function buildCaustics() {
  causticsG.clear();
  causticsG.noStroke();
  for (let i = 0; i < CAUSTICS_DROPLETS; i++) {
    let x = random(width);
    var y = random(height);
    var r = random(40, 160);
    causticsG.fill(255, 240, 200, random(6, 26));
    causticsG.ellipse(x + random(-40, 40), y + random(-40, 40), r, r * random(0.3, 0.9));
  }
}
function buildFog() {
  fogG.clear();
  fogG.noStroke();
  for (let i = 0; i < 180; i++) {
    fogG.fill(10, 30, 60, random(6, 22));
    fogG.ellipse(random(width), random(height), random(120, 420), random(60, 260));
  }
}
/* ============================================================
   珊瑚、海草、气泡
============================================================*/
function addCoral() {
  corals.push({ x: random(width), y: height - random(20, 90), h: random(30, 90), sway: random(1000) });
}
function drawCorals() {
  stroke(255, 140, 160, 200);
  strokeWeight(6);
  for (let c of corals) {
    stroke(255, 140, 170, 190);
    line(c.x, c.y, c.x, c.y - c.h);
    line(c.x, c.y - c.h * 0.5, c.x - 18, c.y - c.h * 0.82);
    line(c.x, c.y - c.h * 0.6, c.x + 18, c.y - c.h * 0.95);
  }
}
function addSeaweed() {
  seaweeds.push({ x: random(width), y: height - 10, h: random(60, 130), offset: random(1000) });
}
function drawSeaweeds() {
  stroke(50, 170, 120, 180);
  strokeWeight(4);
  for (let s of seaweeds) {
    var t = millis() * 0.0012 + s.offset;
    let sway = sin(t) * 26;
    line(s.x, s.y, s.x + sway, s.y - s.h);
  }
}
function drawBubbles() {
  if (random() < 0.04) {
    bubbles.push({
      x: random(width),
      y: height + 20,
      r: random(6, 18),
      alpha: random(80, 220),
      vx: random(-0.2, 0.2)
    });
  }
  noFill();
  strokeWeight(1.5);
  for (let b of bubbles) {
    b.y -= 1.2;
    b.x += b.vx;
    b.alpha -= 0.6;
    stroke(220, 245, 255, b.alpha);
    ellipse(b.x, b.y, b.r, b.r);
  }
  bubbles = bubbles.filter(b => b.alpha > 8 && b.y > -40);
}
/* ============================================================
   小鱼、乌龟、水母、远景鱼（更生动）
============================================================*/
function addFish() {
  fishes.push({
    x: random(width),
    y: random(100, height - 180),
    vx: random(0.3, 1.6),
    vy: 0,
    size: random(14, 28),
    flip: random([1, -1]),
    tailPhase: random(TWO_PI),
    bodyPhase: random(TWO_PI),
    colorHue: random(20, 60),
    depth: random(0.5, 1.3)
  });
}
function drawFishes() {
  noStroke();
  for (let f of fishes) {
    // 更自然的动力学：vx 有轻微加速度与阻尼
    let accel = 0.002 * (1 + sin(millis()*0.0005 + f.bodyPhase));
    f.vx += (accel * f.flip - 0.001 * f.vx); // 平衡阻尼
    f.x += f.vx;
    // 尾摆与身体摆动
    f.tailPhase += 0.18 * f.vx;
    let tailSwing = sin(f.tailPhase) * 6 * f.flip;
    let bob = sin(millis() * 0.002 + f.bodyPhase) * (2 + f.depth);
    // 翻转边界判断（柔和）
    if ((f.x < -60 && f.flip < 0) || (f.x > width + 60 && f.flip > 0)) {
      f.flip *= -1;
      f.vx *= 0.6;
    }
    push();
    translate(f.x, f.y + bob);
    scale(f.flip, 1);
    // 身体层次（渐变）
    for (let i = 0; i < 3; i++) {
      fill(200 - i * 6, 150 + i * 8, 90 + i * 10, 220 - i * 30);
      ellipse(-i * 3, 0, f.size * (1.9 - i * 0.14), f.size * (1.1 - i * 0.12));
    }
    // 眼睛
    fill(20);
    ellipse(f.size * 0.25, -f.size * 0.12, f.size * 0.16, f.size * 0.16);
    // 尾巴
    push();
    translate(-f.size * 0.92, 0);
    rotate(tailSwing * 0.02);
    fill(180, 140, 80, 220);
    triangle(0, 0, -f.size * 0.9, -f.size * 0.6, -f.size * 0.9, f.size * 0.6);
    pop();
    pop();
  }
}
function addTurtle() {
  turtles.push({
    x: random(width),
    y: random(140, height - 220),
    speed: random(0.2, 0.8),
    size: random(36, 58),
    swimPhase: random(TWO_PI)
  });
}
function drawTurtles() {
  for (let t of turtles) {
    t.x += t.speed;
    t.swimPhase += 0.01 * t.speed;
    if (t.x > width + 120) t.x = -120;
    var bob = sin(millis() * 0.0013 + t.swimPhase) * 3;
    push();
    translate(t.x, t.y + bob);
    // 背甲
    noStroke();
    fill(40, 120, 90, 200);
    ellipse(0, 0, t.size * 1.2, t.size * 0.9);
    // 头部
    fill(70, 190, 130, 220);
    ellipse(t.size * 0.38, -t.size * 0.06, t.size * 0.45, t.size * 0.38);
    // 腿划水（摆动）
    fill(60, 160, 110, 220);
    let k = sin(t.swimPhase * 2) * 0.5;
    ellipse(-t.size * 0.25, t.size * 0.25 + k * 6, t.size * 0.5, t.size * 0.22);
    ellipse(t.size * 0.05, t.size * 0.25 - k * 6, t.size * 0.5, t.size * 0.22);
    pop();
  }
}
function addJelly() {
  jellies.push({
    x: random(width),
    y: random(160, height - 240),
    floatOffset: random(0, 1000),
    size: random(22, 44),
    tentPhase: random(TWO_PI)
  });
}
function drawJellies() {
  for (let j of jellies) {
    var t = millis() * 0.0012 + j.floatOffset;
    j.y += sin(t * 0.8 + j.tentPhase) * 0.2;
    j.tentPhase += 0.04;
    push();
    translate(j.x, j.y);
    // 伞盖
    noStroke();
    fill(170, 110, 240, 160);
    ellipse(0, 0, j.size * 1.3, j.size);
    // 触手
    stroke(180, 110, 255, 140);
    strokeWeight(2);
    for (let k = -2; k <= 2; k++) {
      let off = k * j.size * 0.18;
      beginShape();
      for (let s = 0; s < 14; s++) {
        let yy = j.size * 0.45 + s * (j.size * 0.09);
        let xx = off + sin(millis() * 0.0015 + s * 0.4 + j.tentPhase + k) * (6 + k * 2);
        vertex(xx, yy);
      }
      endShape();
    }
    pop();
  }
}
function addFarFish() {
  farFish.push({
    x: random(width),
    y: random(80, height - 320),
    speed: random(0.2, 0.8),
    size: random(10, 18),
    alpha: random(60, 120)
  });
}
function drawFarFish() {
  noStroke();
  for (let f of farFish) {
    f.x += f.speed * 0.6;
    if (f.x > width + 40) f.x = -40;
    fill(200, 210, 255, f.alpha);
    ellipse(f.x, f.y, f.size * 1.8, f.size);
  }
}
